create table batch_sync_logs (agent_related_count integer not null, failed_count integer not null, readme_fetched_count integer not null, saved_count integer not null, searched_count integer not null, skipped_count integer not null, created_at timestamp(6) with time zone not null, ended_at timestamp(6) with time zone, started_at timestamp(6) with time zone not null, id uuid not null, job_name varchar(100) not null, error_message text, status enum ('COMPLETED','FAILED','STARTED') not null, primary key (id));
create table content_reports (created_at timestamp(6) with time zone not null, report_id uuid not null, reporter_id uuid not null, target_id uuid not null, category varchar(80) not null, reason text not null, status enum ('PENDING','REJECTED','RESOLVED','REVIEWED') not null, target_type enum ('DISCUSSION','DISCUSSION_COMMENT','POST','POST_COMMENT','REPOSITORY_ANALYSIS') not null, primary key (report_id));
create table discussion_comments (created_at timestamp(6) with time zone not null, comment_id uuid not null, discussion_id uuid not null, user_id uuid not null, body text not null, primary key (comment_id));
create table discussion_likes (created_at timestamp(6) with time zone not null, discussion_id uuid not null, like_id uuid not null, user_id uuid not null, primary key (like_id), constraint uk_discussion_likes_discussion_user unique (discussion_id, user_id));
create table post_comments (created_at timestamp(6) with time zone not null, comment_id uuid not null, post_id uuid not null, user_id uuid not null, body text not null, primary key (comment_id));
create table post_likes (created_at timestamp(6) with time zone not null, like_id uuid not null, post_id uuid not null, user_id uuid not null, primary key (like_id), constraint uk_post_likes_post_user unique (post_id, user_id));
create table posts (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, post_id uuid not null, user_id uuid not null, image_filename varchar(100), title varchar(200) not null, body text not null, status enum ('ACTIVE','DELETED','HIDDEN') not null, primary key (post_id));
create table repositories (agent_score integer not null, archived boolean not null, fork boolean not null, forks integer not null, is_agent_related boolean not null, open_issues integer not null, stars integer not null, watchers integer not null, created_at timestamp(6) with time zone not null, github_created_at timestamp(6) with time zone, github_id bigint not null unique, github_updated_at timestamp(6) with time zone, last_fetched_at timestamp(6) with time zone, pushed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, agent_category varchar(50), default_branch varchar(100), language varchar(100), name varchar(150) not null, owner varchar(150) not null, license varchar(200), full_name varchar(300) not null unique, clone_url varchar(500), homepage varchar(500), html_url varchar(500), readme_summary varchar(500), description text, description_ko text, topics text, primary key (id));
create table repository_analyses (created_at timestamp(6) with time zone not null, requested_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, repository_id uuid not null, snapshot_id uuid, status varchar(40) not null, error_message TEXT, result_json jsonb, primary key (id));
create table repository_bookmarks (created_at timestamp(6) with time zone not null, id uuid not null, repository_id uuid not null, user_id uuid not null, primary key (id), constraint uk_repository_bookmarks_user_repository unique (user_id, repository_id));
