create table repository_discussions (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, discussion_id uuid not null, repository_id uuid not null, user_id uuid not null, image_filename varchar(100), title varchar(200) not null, body text not null, status enum ('ACTIVE','DELETED','HIDDEN') not null, primary key (discussion_id));
