create table repository_metric_snapshots (captured_on date not null, forks integer not null, open_issues integer not null, stars integer not null, watchers integer not null, created_at timestamp(6) with time zone not null, pushed_at timestamp(6) with time zone, id uuid not null, repository_id uuid not null, primary key (id), constraint uk_repository_metric_snapshot_day unique (repository_id, captured_on));
create table repository_notifications (is_read boolean not null, created_at timestamp(6) with time zone not null, read_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, repository_id uuid not null, user_id uuid not null, type varchar(50) not null, new_sha varchar(100), old_sha varchar(100), change_key varchar(200) not null, message varchar(500) not null, primary key (id), constraint uk_repository_notifications_unique_change unique (user_id, repository_id, type, change_key));
